/**
 * Flash and emulated games from the link doc (ids start at 3001 so they never clash with
 * secretv4_games.json or the Eaglercraft entries). `file` is the Google Drive file id.
 * If a game's link is already in the main library it just gets tagged, not added twice.
 */
export type GameKind = 'flash' | 'emulated';

export interface ExtraGame {
  id: number;
  title: string;
  kind: GameKind;
  /** Console / platform label shown on the card and used for the Emulated filter */
  system: string;
  /** Drive file id, or a full URL */
  file: string;
}

